using System;using System.Text;using UnityEngine;using LWS.TruckSports;using LWS.TruckBowling;
namespace LWS.TruckTargetLaunch {
public enum TargetStage{Countdown,Playing,Settling,Replay,RoundResult}
public sealed class TargetMatch:SportsEventSession {
 public TargetCameras director;public TargetRacer[] racers;public Transform target,precisionZones;public Transform[] landingMarkers;public Collider targetCollider,missGround;public SportsEventCamera[] playerCameras;public SportsEventCamera broadcast;public SportsMotionReplay replay;public SportsChaosWeather atmosphere;public TargetRules rules=new TargetRules();public int seed=42761;public TargetStage Stage{get;private set;}public float Clock{get;private set;}public float Timer{get;private set;}public Vector3 CurrentWind{get;private set;}public int HumanViews{get;private set;}public int[] Owners{get;private set;}=new int[4];public bool RoundLive=>Stage==TargetStage.Playing||Stage==TargetStage.Settling;
 readonly Vector3[] aim=new Vector3[4];readonly float[] speed=new float[4],think=new float[4];readonly Vector2[] ai=new Vector2[4];readonly bool[] dive=new bool[4];readonly StringBuilder text=new StringBuilder(600);int display=-1;float recordTime;
 public override string Title=>"TRUCK TARGET LAUNCH";public override int MinimumPlayers=>1;public override int MaximumPlayers=>4;public override int OptionCount=>1;public override int WeatherCount=>1;public override string OptionLabel=>"FIVE SIMULTANEOUS LAUNCHES";public override bool MultiViewHUD=>HumanViews>0&&Stage!=TargetStage.Replay&&Stage!=TargetStage.RoundResult;public override bool ReplayControls=>Stage==TargetStage.Replay;
 public override string Help=>"Your truck is the projectile. Drive down the wide slope and up the real curved launch ramp. Speed, entry line and direction determine the flight. Adjacent competitors can physically jostle and collide in the air. No automatic scoring trajectory is supplied. Small wings unfold after leaving the lip. Limited horizontal aftertouch nudges the path; release forward/back once to arm range correction. Total correction is bounded; gravity always remains downward. ACTION dives once: wings fold, lift ends and descent becomes heavier. The same controls, grip, momentum, aftertouch and dive apply to AI.\n\nFirst valid descending contact on the target's TOP locks the projected chassis-center score:10outer,25middle,50precision,100tiny bullseye. Smaller zones have inclusive edges and take precedence. Side/underside contacts do not score. Later bumps, slides, crashes and falls cannot revoke or increase a locked result. Missed approach, ground crash or generous simulation timeout scores zero.\n\nFive launches each; total points win. Tied leaders receive equal-opportunity extra launches until resolved. Solo stores a personal best. Starts rotate; wind, target layout and moving precision sections are shared by everyone in a round. Later rounds increase visible wind and slowly move the precision zone. Each human keeps an independent stable chase pane; AI-only uses a broadcast. Once all resolve, a shared actual-motion replay offers angle, speed, rewind and skip. Pause/reconnect preserves bodies, attempts and scores; release and freshly confirm after source replacement. Offline only.";
 public override string Header=>Title+" · "+(rules.Round<=5?"LAUNCH "+rules.Round+" / 5":"EXTRA ROUND "+rules.ExtraRound)+(Stage==TargetStage.Countdown?" · "+Mathf.CeilToInt(Timer):"");public override string Status=>Stage==TargetStage.Replay?"ACTUAL SHARED REPLAY · "+replay.Speed.ToString("0.##")+"× · CAMERA "+(replay.Angle+1):"WIND "+(CurrentWind.magnitude*2.236936f).ToString("F1")+" MPH · "+(CurrentWind.x>=0?"RIGHT":"LEFT")+" · 10 / 25 / 50 / 100";
 public override string Standings{get{text.Clear();for(int i=0;i<setup.count;i++)text.Append(setup.players[i].name).Append("  ").Append(rules.totals[i]).Append(" PTS · ").Append(rules.attempts[i]).Append(" LAUNCHES\n");return text.ToString();}}
 public override string Results=>(setup.count==1?"SOLO TOTAL "+rules.totals[0]+" · BEST "+SportsPrefs.GetInt("TruckTargetLaunch.Best",0):rules.Winner>=0?setup.players[rules.Winner].name+" WINS":"COMPLETE")+"\n\n"+Standings;
 public override string ViewText(int view){int owner=HumanViews==0?0:Owners[view];var r=racers[owner];return "<color=#"+ColorUtility.ToHtmlStringRGB(setup.players[owner].color)+">"+setup.players[owner].name+"</color> · "+rules.totals[owner]+" PTS · LAUNCH "+rules.Round+"\n"+(rules.resolved[owner]?(rules.last[owner]>0?"LANDED · "+rules.last[owner]+" POINTS":"MISS · WAITING"):r.Phase==TargetFlight.Passive?"CONTACT · NO AIR CONTROL":r.Phase==TargetFlight.Approach?"DRIVE / ALIGN · "+(r.truck.body.linearVelocity.magnitude*2.236936f).ToString("F0")+" MPH":(r.Dived?"DIVE COMMITTED":"ACTION: DIVE ONCE")+" · AFTERTOUCH "+Mathf.RoundToInt(Mathf.Max(0,1-r.touch.Spent/1.6f)*100)+"%")+"\nWIND "+(CurrentWind.magnitude*2.236936f).ToString("F1")+" MPH · TARGET 10 / 25 / 50 / 100";}
 protected override void BeginGame(){rules.Reset(setup.count);RoundStart();}
 void RoundStart(){Clock=recordTime=0;Timer=3;Stage=TargetStage.Countdown;var random=new System.Random(seed+rules.Round*7919);target.position=new Vector3(rules.Round<=2?0:(float)(random.NextDouble()*6-3),4,130+(rules.Round<=2?0:(float)(random.NextDouble()*8-4)));target.gameObject.SetActive(true);precisionZones.localPosition=PrecisionCenterAt(0);foreach(var marker in landingMarkers)marker.localScale=Vector3.zero;atmosphere.Configure(seed+rules.Round*101,weather+1,rules.Round>2?1:0);CurrentWind=atmosphere.Flow*Mathf.Lerp(.6f,2.2f,Mathf.Clamp01((rules.Round-1)/4f));for(int i=0;i<4;i++){bool active=i<setup.count&&(rules.Eligible&(1<<i))!=0;racers[i].gameObject.SetActive(active);if(!active)continue;int start=(i+rules.Round-1)%setup.count;float x=(start-(setup.count-1)*.5f)*3;racers[i].ResetRacer(new Vector3(x,34.2f,2));float skill=(int)setup.players[i].difficulty;float error=(float)(random.NextDouble()*2-1)*Mathf.Lerp(9,2.5f,skill*.5f);aim[i]=target.position+new Vector3(error,0,(float)(random.NextDouble()*2-1)*Mathf.Lerp(7,2,skill*.5f));speed[i]=24.7f+(float)(random.NextDouble()-.5)*Mathf.Lerp(2.5f,.5f,skill*.5f);think[i]=0;ai[i]=Vector2.zero;dive[i]=false;}Layout();var colors=new[]{setup.players[0].color,setup.players[1].color,setup.players[2].color,setup.players[3].color,Color.white};replay.Colorize(colors);for(int i=0;i<4;i++){var block=new MaterialPropertyBlock();block.SetColor("_BaseColor",colors[i]);landingMarkers[i].GetComponent<Renderer>().SetPropertyBlock(block);replay.ghosts[4].Find(landingMarkers[i].name).GetComponent<Renderer>().SetPropertyBlock(block);}replay.ResetRecord();Gate();}
 void Layout(){HumanViews=0;for(int i=0;i<setup.count;i++)if(setup.players[i].source!=BowlingSource.AI)Owners[HumanViews++]=i;for(int i=0;i<4;i++)playerCameras[i].view.enabled=false;broadcast.view.enabled=HumanViews==0;display=-1;RefreshCameras(false);}
 void RefreshCameras(bool replaying){if(replaying||HumanViews==0){foreach(var c in playerCameras)c.view.enabled=false;broadcast.view.enabled=true;broadcast.view.rect=new Rect(0,0,1,1);cameras=new[]{broadcast.view};return;}if(display==HumanViews)return;display=HumanViews;cameras=new Camera[HumanViews];broadcast.view.enabled=false;for(int i=0;i<HumanViews;i++){var c=playerCameras[Owners[i]].view;c.enabled=true;c.rect=LWS.TruckCornhole.CornholeMatch.ViewRect(HumanViews,i);cameras[i]=c;}}
 public Vector3 PrecisionCenterAt(float time){if(rules.Round<3)return Vector3.zero;float angle=time*.045f+(rules.Round-3)*.7f;return new Vector3(Mathf.Cos(angle)*6.5f,0,Mathf.Sin(angle)*6.5f);}
 public int ScoreAt(Vector3 world){var local=target.InverseTransformPoint(world);var inner=PrecisionCenterAt(Clock);return TargetRules.Zone(local.x,local.z,inner.x,inner.z);}
 protected override void Simulate(float dt){if(Stage==TargetStage.Countdown){foreach(var racer in racers)if(racer.gameObject.activeSelf){racer.truck.TickDrive(Vector2.zero);foreach(var wheel in racer.truck.wheels)wheel.BrakeTorque=racer.truck.brakeTorque;}Timer-=dt;if(Timer<=0)Stage=TargetStage.Playing;return;}if(Stage==TargetStage.Replay){if(replay.Step(dt)||Timer<0){replay.End();target.gameObject.SetActive(true);for(int i=0;i<setup.count;i++)racers[i].gameObject.SetActive((rules.Eligible&(1<<i))!=0);Stage=TargetStage.RoundResult;Timer=1.5f;}return;}if(Stage==TargetStage.RoundResult){Timer-=dt;if(Timer<=0){rules.Advance();if(rules.Complete){if(setup.count==1){SportsPrefs.SetInt("TruckTargetLaunch.Best",Mathf.Max(rules.totals[0],SportsPrefs.GetInt("TruckTargetLaunch.Best",0)));SportsPrefs.Save();}EndMatch();}else RoundStart();}return;}
  for(int i=0;i<setup.count;i++)if(racers[i].gameObject.activeSelf)racers[i].ObservePastStep();Clock+=dt;atmosphere.Tick(Clock);CurrentWind=atmosphere.Flow*Mathf.Lerp(.6f,2.2f,Mathf.Clamp01((rules.Round-1)/4f));precisionZones.localPosition=PrecisionCenterAt(Clock);int mask=1<<4;for(int i=0;i<setup.count;i++){if(!racers[i].gameObject.activeSelf)continue;mask|=1<<i;var input=commands[i];bool action=actions[i];if(setup.players[i].source==BowlingSource.AI){Bot(i,dt);input=ai[i];action=dive[i];}racers[i].Tick(input,action,dt);}recordTime+=dt;replay.Record(recordTime,mask);if(Stage==TargetStage.Playing&&rules.RoundComplete){Stage=TargetStage.Settling;Timer=0;}if(Stage==TargetStage.Settling){Timer+=dt;if(Timer>=2.8f)BeginReplay();}}
 void BeginReplay(){replay.Record(recordTime+.051f,rules.Eligible|(1<<4));foreach(var r in racers){r.Freeze();r.gameObject.SetActive(false);}target.gameObject.SetActive(false);Stage=TargetStage.Replay;Timer=0;replay.Begin(Mathf.Max(0,recordTime-7));RefreshCameras(true);Gate();}
 public void Lock(int slot,int score,Vector3 point){if(!RoundLive||!rules.Lock(slot,score))return;if(score>0){var marker=landingMarkers[slot];var local=target.InverseTransformPoint(point);marker.localPosition=new Vector3(local.x,.15f+slot*.015f,local.z);marker.localScale=Vector3.one;var block=new MaterialPropertyBlock();block.SetColor("_BaseColor",setup.players[slot].color);marker.GetComponent<Renderer>().SetPropertyBlock(block);}feedback.Play(score==100?5:score>0?2:3,0,true);Pulse(slot,score==100?.65f:.3f,.18f);Debug.Log("TARGET_LANDING round="+rules.Round+" slot="+slot+" score="+score+" point="+point+" dive="+racers[slot].Dived+" aftertouch="+racers[slot].touch.Spent);}
 public void Launched(int slot,Vector3 velocity){feedback.Play(0,0,true);Pulse(slot,.25f,.12f);Debug.Log("TARGET_ACTUAL_RAMP_RELEASE slot="+slot+" velocity="+velocity);}
 public void Dived(int slot){feedback.Play(4,0,true);Pulse(slot,.15f,.1f);}public void Impact(int slot,float speed){feedback.Play(1,speed);Pulse(slot,Mathf.Clamp01(speed*.02f),.1f);}
 float FlightTime(TargetRacer racer,bool diving){var body=racer.truck.body;float g=Physics.gravity.magnitude*(diving?1.18f:.76f),dy=Mathf.Max(0,body.position.y-target.position.y);return Mathf.Max(0,(body.linearVelocity.y+Mathf.Sqrt(body.linearVelocity.y*body.linearVelocity.y+2*g*dy))/g);}
 void Bot(int slot,float dt){dive[slot]=false;think[slot]-=dt;if(think[slot]>0)return;float skill=(int)setup.players[slot].difficulty;think[slot]=Mathf.Lerp(.26f,.08f,skill*.5f);var racer=racers[slot];var body=racer.truck.body;if(racer.Phase==TargetFlight.Approach){float remaining=Mathf.Max(28,aim[slot].z-body.position.z);var direction=new Vector3(aim[slot].x-body.position.x,0,remaining);float angle=Vector3.SignedAngle(Vector3.ProjectOnPlane(body.rotation*Vector3.forward,Vector3.up),direction,Vector3.up);float throttle=Mathf.Clamp((speed[slot]-body.linearVelocity.z)*.6f,-.65f,1);ai[slot]=new Vector2(Mathf.Clamp(angle/32,-1,1),throttle);return;}if(racer.Phase==TargetFlight.Airborne){float time=FlightTime(racer,racer.Dived);Vector3 predicted=body.position+body.linearVelocity*time+CurrentWind*(.009f*time*time);Vector3 intended=aim[slot]+(rules.Round>=3?PrecisionCenterAt(Clock+time)*Mathf.Lerp(.15f,.85f,skill*.5f):Vector3.zero);float gain=Mathf.Lerp(.08f,.18f,skill*.5f);ai[slot]=new Vector2(Mathf.Clamp((intended.x-predicted.x)*gain,-1,1),racer.FlightAge<.35f?0:Mathf.Clamp((intended.z-predicted.z)*gain,-1,1));if(!racer.Dived&&racer.FlightAge>.55f){float divedZ=body.position.z+body.linearVelocity.z*FlightTime(racer,true);dive[slot]=predicted.z>intended.z+5&&Mathf.Abs(divedZ-intended.z)+2<Mathf.Abs(predicted.z-intended.z);}return;}ai[slot]=Vector2.zero;}
 public override void ExtraAction(string key){if(Stage!=TargetStage.Replay)return;if(key=="replayangle")replay.Angle=(replay.Angle+1)%3;else if(key=="replayspeed")replay.Speed=replay.Speed==1?.5f:replay.Speed==.5f?2:1;else if(key=="replayrewind")replay.Seek(Mathf.Max(0,replay.Cursor-3));else if(key=="replayskip")Timer=-1;ConsumeActions();}
 protected override void Present(float dt){if(director!=null)director.Present(dt);}
 protected override void SetPaused(bool paused){if(atmosphere!=null)atmosphere.Pause(paused);}protected override void StopGame(){if(replay!=null)replay.End();if(racers!=null)foreach(var r in racers)if(r!=null)r.Freeze();}protected override void StopSounds(){if(racers!=null)foreach(var r in racers)if(r!=null){if(r.truck!=null)r.truck.StopSound();if(r.wind!=null)r.wind.Stop();}}
}
